{
  "operationName": "WikidataSearch",
  "query": "query WikidataSearch($query: String!, $language: String, $limit: Int) {\n  wikidataSearch(query: $query, language: $language, limit: $limit) {\n    qid\n    label\n    description\n    entityType\n  }\n}\n",
  "variables": {
    "query": "{{search_query}}",
    "language": "{{language}}",
    "limit": "{{limit}}"
  }
}

